#include <stdint.h>
#include <stdio.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

typedef struct
{
	short crc;
	char status;
	uint16_t payload;
	int bat;
	int sensor;
	uint8_t longAddr;
	short shortAddr;
	char addrMode;
} Packet_t;

void CollectPacketData(Packet_t *pData, uint32_t rawData);
void PrintPacketData(Packet_t *pData);

int main(void)
{
	Packet_t packet;
	Packet_t *pPacket = &packet;
	uint32_t rawData;

	printf("Enter the 32bit packet:\n");
	scanf("%X32I\n", &rawData);

	CollectPacketData(pPacket, rawData);
	PrintPacketData(pPacket);

	getchar();
    /* Loop forever */
	for(;;);
}

void CollectPacketData(Packet_t *pData, uint32_t rawData)
{
	pData->crc = rawData & 0x03;

	pData->status = (rawData >> 2) & 0x01;

	pData->payload = (rawData >> 3) & 0x0FFF;

	pData->bat = (rawData >> 15) & 0x06;

	pData->sensor = (rawData >> 18) & 0x06;

	pData->longAddr = (rawData >> 21) & 0xFF;

	pData->shortAddr = (rawData >> 29) & 0x03;

	pData->addrMode = (rawData >> 31) & 0x01;
}

void PrintPacketData(Packet_t *pData)
{
	printf("crc: %d\n", pData->crc);
	printf("status: %d\n", pData->status);
	printf("payload: %d\n", pData->payload);
	printf("bat: %d\n", pData->bat);
	printf("sensor: %d\n", pData->sensor);
	printf("longAddr: %d\n", pData->longAddr);
	printf("shortAddr: %d\n", pData->shortAddr);
	printf("addrMode: %d\n", pData->addrMode);
}
